INSERT INTO recalc_admin.campus_academic_fee(id,"campusId","academicFeeId","isActive","overrideCostMxn","createdAt","updatedAt")
SELECT d.id::uuid,c.id,f.id,d.active,d.override_cost::integer,now(),now()
FROM data d JOIN recalc_admin.campus c ON lower(c.name)=lower(d.plantel)
JOIN recalc_admin.academic_fee f ON f.code=d.code
ON CONFLICT ("campusId","academicFeeId") DO UPDATE SET "isActive"=excluded."isActive","overrideCostMxn"=excluded."overrideCostMxn","updatedAt"=now();
