INSERT INTO recalc_admin.program_offering(id,"campusId","programId",cycle,track,delivery,escolarizado,ejecutivo,"escolarizadoSchedule","ejecutivoSchedule","lineOfBusiness","pricingPlans",module_count,subjects_by_module,"isActive","updatedBy","createdAt","updatedAt")
SELECT d.id::uuid,c.id,p.id,d.cycle,d.track,d.delivery::recalc_admin."ProgramOfferingDelivery",d.esc,d.eje,d.esc_schedule,d.eje_schedule,d.line,d.pricing,d.module_count,d.subjects,true,'import-2026-c3',now(),now()
FROM data d JOIN recalc_admin.campus c ON lower(c.name)=lower(d.plantel)
JOIN recalc_admin.program p ON p."nameNormalized"=d.normalized
ON CONFLICT ("campusId","programId",cycle,track) DO UPDATE SET delivery=excluded.delivery,escolarizado=excluded.escolarizado,ejecutivo=excluded.ejecutivo,"escolarizadoSchedule"=excluded."escolarizadoSchedule","ejecutivoSchedule"=excluded."ejecutivoSchedule","lineOfBusiness"=excluded."lineOfBusiness","pricingPlans"=excluded."pricingPlans",module_count=excluded.module_count,subjects_by_module=excluded.subjects_by_module,"isActive"=true,"updatedBy"='import-2026-c3',"updatedAt"=now();
