INSERT INTO recalc_admin.scholarship_rule(id,"enrollmentType","businessLine",modality,plan,"campusTier",region,plantel,"programaKey","minAverage","maxAverage","scholarshipPercent","discountedPriceMxn",origin,"sourceVersion","createdAt","updatedAt")
